-- ============================================================================
-- 048: fusion de los dos cursos de custodia dentro de "Seguridad basica en
--      Bitcoin y criptomonedas"
-- ============================================================================
-- Aplicada en produccion el 2026-09-24. Este fichero refleja el estado
-- resultante, leido de la base despues de aplicarla.
--
-- QUE HACE
--   1. Reescribe la ruta "Seguridad en Criptomonedas" (textos).
--   2. El curso pasa de 2 modulos / 6 lecciones a 3 modulos / 9 lecciones.
--      Las 6 lecciones que ya existian conservan su id, y con el todo el
--      user_progress asociado. Se crean 3 lecciones y 1 modulo.
--   3. Sustituye las 5 preguntas de quiz por 27 (9 por modulo).
--   4. Mueve "Cold Storage" a la ruta seguridad-cripto y elimina la ruta
--      seguridad-avanzada, que se queda sin cursos.
--   5. Archiva los dos cursos de custodia, cuyo contenido queda absorbido.
--   6. Recalcula progress_percentage de las 2 matriculas del curso.
--
-- QUE NO TOCA, A PROPOSITO
--   completed_at ni los certificados. Los 2 certificados emitidos siguen
--   siendo validos: el certificado congela lo que se completo entonces y el
--   porcentaje refleja el presente.
--
--   Los 3 intentos de quiz previos. Viven en quiz_attempts, referencian
--   module_id (que sigue existiendo) y guardan los question_id dentro de un
--   JSONB sin clave ajena, asi que borrar las preguntas no los arrastra.
--
--   Las 6 matriculas y las 4 filas de progreso de los cursos archivados. Se
--   conservan en la base; dejan de mostrarse porque RLS ya no sirve un curso
--   archivado a un usuario normal.
--
-- OJO CON EL DISPARADOR DE LA 030
--   trigger_course_modification devuelve a 'pending_review' cualquier curso
--   publicado cuyo title/description/long_description cambie, salvo que quien
--   escribe sea admin o la transaccion fije app.skip_republish_check = on.
--   Al aplicar esto por PostgREST no hay ninguna de las dos cosas, asi que el
--   curso se cayo de produccion sin aviso. El bloque 7 lo devuelve. Si se
--   ejecuta este fichero por SQL, la renuncia del bloque 0 ya lo evita.
--
-- RESPALDO
--   C:/Users/alber/backups-sql/048-volver-atras.sql.bak (filas completas, con
--   slug). No restaura el modulo ni las 3 lecciones nuevas: hay que borrarlos
--   a mano, y sus ids estan al final de este fichero.
-- ============================================================================

BEGIN;

-- 0. Renuncia al disparador de republicacion, de alcance transaccional.
SET LOCAL app.skip_republish_check = 'on';

-- ============================================================================
-- 1. Ruta "Seguridad en Criptomonedas"
-- ============================================================================

UPDATE public.learning_paths SET
  subtitle = 'De no perderlo por un descuido a no perderlo nunca',
  short_description = 'Reconocer las estafas, proteger tus accesos y custodiar lo que guardas. De los hábitos básicos al almacenamiento sin conexión.',
  long_description = 'La mayoría de los fondos que se pierden en cripto no se los lleva un atacante sofisticado: se van en una dirección mal copiada, una copia de seguridad que nunca se comprobó o un mensaje que llegó en el momento justo.

Esta ruta se ocupa de eso, en orden. Primero los riesgos reales del ecosistema y los errores que de verdad cuestan dinero. Después la parte que casi ningún curso trata: proteger los accesos, los dispositivos y las cuentas que son la llave de todo lo demás. Y por último la custodia, planteada como una decisión con criterio y no como una consigna, hasta llegar al almacenamiento sin conexión para lo que no piensas tocar.

No hace falta ser técnico ni vivir en tensión. Lo que protege son unas pocas costumbres bien colocadas en los momentos que importan.'
 WHERE slug = 'seguridad-cripto';

-- ============================================================================
-- 2. Modulos
-- ============================================================================

-- M1 Los riesgos reales
UPDATE public.modules SET title = 'Los riesgos reales', slug = 'riesgos-reales-en-el-mundo-cripto',
  description = 'Qué trabajos asumes al custodiar tú, cómo funcionan las estafas del ecosistema y cuáles son los errores que de verdad cuestan dinero. El objetivo no es generar miedo, sino criterio.', order_index = 0
 WHERE id = '7b2773a3-5633-4242-a099-d3a2c2622ca2';

-- M2 Proteger tus accesos
UPDATE public.modules SET title = 'Proteger tus accesos', slug = 'proteger-tus-accesos',
  description = 'Contraseñas, segundo factor, dispositivos y las cuentas que recuperan todas las demás. Es la parte que casi ningún curso de cripto trata y la que sostiene todo lo demás.', order_index = 1
 WHERE id = '9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b';

-- M3 La custodia, decidida con criterio  (NUEVO)
INSERT INTO public.modules (id, course_id, title, slug, description, order_index, requires_quiz)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '920653af-6b9d-4e91-8c13-cfbf71d9a539', 'La custodia, decidida con criterio', 'la-custodia-decidida-con-criterio', 'Qué se custodia exactamente, qué falla en cada opción y cómo decidir tu reparto entre custodia propia y custodios terceros. Con criterios, no con consignas.', 2, FALSE)
ON CONFLICT (id) DO NOTHING;

-- ============================================================================
-- 3. Lecciones
-- ============================================================================
-- Primero se apartan a order_index altos las que ya existian, para que los
-- movimientos entre modulos no choquen con (module_id, order_index).

UPDATE public.lessons SET order_index = order_index + 90 WHERE course_id = '920653af-6b9d-4e91-8c13-cfbf71d9a539';

-- 1.1 que-significa-ser-tu-propio-banco
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('a36d9b91-85a0-4be5-a361-598a53e30dd6', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Qué significa ser tu propio banco', 'que-significa-ser-tu-propio-banco', 'Qué hace un banco sin que lo veas, qué trabajos pasan a ser tuyos y por qué no es una cuestión de todo o nada.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Ver con precisión qué trabajos hace un banco por ti sin que te enteres, cuáles pasan a ser tuyos al custodiar tú, y por qué eso no es una cuestión de todo o nada.</p><hr><h3>🏦 Lo que hace un banco y nunca ves</h3><p>La frase «ser tu propio banco» se repite tanto que ha perdido el significado. Recuperarlo exige una pregunta que casi nadie se hace: <strong>¿qué hace exactamente un banco?</strong></p><p>Guardar dinero es lo de menos. Un banco, detrás de esa aplicación, sostiene un montón de trabajo continuo:</p><ul><li><p><strong>Vigila el fraude.</strong> Hay sistemas mirando tus movimientos y bloqueando lo que se sale del patrón. Cuando te llaman para preguntar si esa compra era tuya, eso es el trabajo asomando.</p></li><li><p><strong>Deshace errores.</strong> Un cargo duplicado, una transferencia al destinatario equivocado dentro de plazo, una suscripción que no recordabas. Hay un procedimiento y alguien que lo ejecuta.</p></li><li><p><strong>Te devuelve el acceso.</strong> Olvidas la contraseña, pierdes el teléfono, te roban la tarjeta. Hay una forma de demostrar que eres tú y volver a entrar.</p></li><li><p><strong>Guarda copias.</strong> Si sus servidores arden, tu saldo no desaparece. Tienen redundancia y obligación legal de mantenerla.</p></li><li><p><strong>Responde con un fondo de garantía.</strong> Si la entidad quiebra, hay un sistema público que cubre los depósitos hasta un límite.</p></li></ul><p>Nada de eso se ve mientras funciona. Es exactamente el tipo de trabajo que solo se nota cuando falta.</p><hr><h3>🔄 Los cuatro trabajos que pasan a ser tuyos</h3><p>Al custodiar tú, esa lista no desaparece: <strong>cambia de manos</strong>. Y conviene mirarla como lo que es, un traspaso de tareas concretas y no una idea abstracta de libertad.</p><ul><li><p><strong>La custodia.</strong> Decidir dónde vive el acceso a tus fondos y protegerlo de robo, pérdida y deterioro.</p></li><li><p><strong>La recuperación.</strong> Asegurarte de que existe una forma de volver a entrar si tu dispositivo desaparece. Nadie más la va a preparar por ti, y no se improvisa después.</p></li><li><p><strong>La verificación.</strong> Comprobar que la dirección, la cantidad y el destino son los correctos antes de firmar. Aquí no hay sistema antifraude mirando por encima del hombro.</p></li><li><p><strong>La detección de engaños.</strong> Reconocer cuándo alguien está intentando manipularte. Es el trabajo que más pérdidas evita y el único que no se puede delegar en una herramienta.</p></li></ul><p>Este curso se ocupa de los cuatro. El módulo 2 se centra en la recuperación y en proteger el acceso; el módulo 3, en la custodia. La detección de engaños empieza en la lección siguiente, porque es la más urgente.</p><hr><h3>⚖️ La asimetría que conviene entender</h3><p>Lo que ganas y lo que pagas no tienen la misma forma, y esa diferencia explica casi todo lo demás.</p><p><strong>Lo que ganas es permanente y pasivo.</strong> Nadie puede congelar tus fondos, ni cerrarte el acceso, ni decidir que tu operación no procede, ni desaparecer llevándose lo tuyo. Eso está ahí todos los días sin que tengas que hacer nada.</p><p><strong>Lo que pagas es puntual y activo.</strong> Se cobra por errores, uno a uno, en el momento exacto en que ocurren. Y cada cobro es definitivo.</p><p>De ahí sale la consecuencia práctica más útil de esta lección: <strong>el riesgo no se reparte de forma uniforme en el tiempo</strong>. Se concentra en unos pocos instantes —cuando configuras algo, cuando firmas, cuando alguien te escribe— y es despreciable el resto del tiempo.</p><p>Lo que significa que no hace falta vivir en tensión. Hace falta reconocer esos instantes y bajar el ritmo en ellos.</p><hr><h3>🎭 Por qué el lema se queda corto</h3><p>«Ser tu propio banco» sugiere que has adquirido una caja fuerte. Lo que has adquirido es <strong>un departamento entero</strong>, y estás tú solo en él.</p><p>Esto no es un argumento en contra: es la descripción correcta del trabajo. Y ayuda a detectar dos errores opuestos que se cometen a partes iguales.</p><ul><li><p><strong>Creer que ya lo eres</strong> cuando en realidad usas una plataforma que custodia por ti. Como vimos en <em>Uso práctico de Bitcoin</em>, tener saldo en una empresa es tener un derecho de cobro contra ella. Es una opción legítima, pero no es esto.</p></li><li><p><strong>Creer que basta con comprar un aparato.</strong> Un dispositivo dedicado resuelve una parte de la custodia. No hace las copias, no ensaya la recuperación y no detecta que quien te escribe miente.</p></li></ul><hr><h3>📊 No es todo o nada</h3><p>Se presenta como una elección entre dos bandos, y no lo es. Casi nadie custodia el cien por cien de lo suyo, del mismo modo que casi nadie lleva todos sus ahorros en efectivo.</p><p>Lo razonable es <strong>decidirlo por cantidades y por usos</strong>: qué parte necesitas a mano, qué parte no piensas tocar en meses, y cuánta responsabilidad quieres asumir hoy con la experiencia que tienes hoy.</p><p>Cómo se decide esa proporción en la práctica está en <em>Uso práctico de Bitcoin</em>, y el esquema completo para lo que guardas, en <em>Cold Storage</em>. Aquí basta con retener que la pregunta correcta no es «¿custodio o no custodio?», sino <strong>«¿cuánto, y con qué preparación?»</strong>.</p><hr><h3>🧭 Lo que este curso da por supuesto</h3><p>Una advertencia honesta antes de seguir, porque marca el tono del resto.</p><p>Este curso no va a decirte que la autocustodia es mejor. Va a enseñarte a hacerla bien <strong>si decides hacerla</strong>, y a reconocer cuándo no estás preparado para una cantidad determinada.</p><p>Tampoco va a pedirte que vivas con miedo. La mayoría de las pérdidas que verás en la lección siguiente no le ocurren a gente descuidada: le ocurren a gente normal en un mal momento. Contra eso funcionan las costumbres, no la desconfianza permanente.</p><hr><h3>📌 En resumen</h3><ul><li><p>Un banco no solo guarda dinero: <strong>vigila el fraude, deshace errores, te devuelve el acceso, guarda copias y responde con un fondo de garantía</strong>. Todo eso es invisible mientras funciona.</p></li><li><p>Al custodiar tú, esos trabajos no desaparecen: <strong>cambian de manos</strong>. Son cuatro: custodia, recuperación, verificación y detección de engaños.</p></li><li><p>Lo que ganas es <strong>permanente y pasivo</strong>; lo que pagas es <strong>puntual, activo y definitivo</strong>.</p></li><li><p>El riesgo se concentra en pocos instantes. No hace falta tensión constante: hace falta reconocerlos.</p></li><li><p>No has adquirido una caja fuerte, sino un departamento entero, y estás solo en él.</p></li><li><p>No es todo o nada. La pregunta no es «¿custodio?», sino <strong>«¿cuánto, y con qué preparación?»</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>De los cuatro trabajos, hay uno que se cobra antes que los demás y no espera a que estés listo: <strong>alguien va a intentar engañarte</strong>. En la siguiente lección vemos cómo funcionan las estafas del ecosistema, qué señales comparten todas y por qué la más peligrosa no parece una estafa.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 1.2 estafas-mas-habituales
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('35de1dee-62bb-464e-9654-e2e48c7f8c1f', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Estafas más habituales', 'estafas-mas-habituales', 'Reconocer las estafas por su estructura y no por su apariencia, y por qué la más peligrosa no lo parece.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Reconocer las estafas del ecosistema por su estructura y no por su apariencia, porque la apariencia cambia cada temporada y la estructura no. Y entender por qué la más peligrosa es justamente la que no lo parece.</p><hr><h3>🧬 Todas tienen la misma forma</h3><p>Da igual que llegue como una oportunidad de inversión, un regalo de monedas o un soporte técnico amable: por debajo, casi todas hacen lo mismo en el mismo orden.</p><ol><li><p><strong>Consiguen tu atención</strong> con algo que te interesa: ganar, recuperar, arreglar, no quedarte fuera.</p></li><li><p><strong>Establecen una razón para confiar</strong>: una marca conocida, un perfil con seguidores, una web cuidada, alguien que parece saber.</p></li><li><p><strong>Introducen tiempo</strong>. Una fecha límite, unas plazas, un precio que sube. La prisa no es decorado: es la pieza que impide pensar.</p></li><li><p><strong>Piden una acción irreversible</strong>: un envío, una firma, unas palabras de recuperación.</p></li></ol><p>Aprenderse el catálogo de estafas concretas sirve poco, porque cambia. Reconocer estos cuatro pasos sirve siempre, incluso con las que todavía no existen.</p><hr><h3>💰 La promesa de rentabilidad</h3><p>Es la más común y la más fácil de descartar, porque se apoya en algo que sencillamente no existe.</p><p><strong>En cripto no hay rendimientos garantizados.</strong> No es que sean raros: es que nadie puede garantizarlos, porque el valor de lo que hay debajo se mueve y no lo controla nadie. Cualquiera que asegure una cifra fija está prometiendo algo que no está en su mano cumplir.</p><p>Formas habituales: plataformas que ofrecen un porcentaje mensual, «bots» que operan por ti, grupos privados con señales, proyectos que reparten beneficios entre quienes entran.</p><p>Muchos pagan al principio. Es parte del método: pagar a los primeros con el dinero de los siguientes convierte a los primeros en recomendadores convencidos, que es la publicidad más eficaz que existe.</p><p><strong>La regla:</strong> rentabilidad garantizada y cripto son incompatibles. Sin excepciones, sin matices y sin que importe quién lo diga.</p><hr><h3>🎁 Los regalos que cuestan todo</h3><p>Te dicen que tienes derecho a unas monedas gratuitas por algo que ya hiciste: usar cierta aplicación, tener cierto saldo, estar en una lista. Solo hay que reclamarlas.</p><p>Reclamarlas siempre implica una de tres cosas: conectar tu cartera a una web, firmar una operación que no entiendes, o introducir tus palabras de recuperación para «verificar».</p><p>La tercera es un robo directo. Las dos primeras son más sutiles: lo que firmas puede ser un permiso para que un contrato mueva tus fondos cuando quiera, no un cobro.</p><p><strong>La regla:</strong> nadie necesita acceso a tu cartera para darte algo. Recibir requiere una dirección y nada más, como vimos en <em>Uso práctico de Bitcoin</em>.</p><hr><h3>🎭 La suplantación</h3><p>Alguien se hace pasar por quien tú ya conoces: el soporte de una plataforma, una persona conocida del sector, una marca.</p><p>Las señales que lo delatan son de método, no de contenido:</p><ul><li><p><strong>Te escriben primero.</strong> Las empresas legítimas no inician conversaciones privadas para ofrecerte ayuda que no has pedido.</p></li><li><p><strong>Te sacan del sitio oficial.</strong> «Sigamos por privado», «entra en este enlace», «instala esto para que lo veamos mejor».</p></li><li><p><strong>Meten prisa.</strong> Siempre.</p></li></ul><p>Fíjate en que ninguna depende de detectar una falta de ortografía o un logotipo mal puesto. Eso funcionaba hace años; hoy las imitaciones son buenas.</p><hr><h3>🏗️ Los proyectos que existen para estafar</h3><p>Aquí no hay un mensaje privado ni un enlace falso: hay un proyecto entero, con su web, su documentación y su comunidad, construido para recoger dinero y desaparecer.</p><p>Señales que comparten casi todos:</p><ul><li><p><strong>Equipo sin trayectoria comprobable</strong>, o directamente anónimo, pidiendo dinero.</p></li><li><p><strong>Más marketing que producto.</strong> Mucho sobre lo que va a valer, poco sobre lo que hace.</p></li><li><p><strong>Plazos y cifras concretas</strong> sobre el futuro, que nadie puede conocer.</p></li><li><p><strong>Un ambiente que castiga las preguntas.</strong> Si preguntar cómo funciona algo te convierte en enemigo de la comunidad, esa comunidad no está para aprender.</p></li></ul><p>Este último es el más fiable y el menos citado. Un proyecto sólido agradece las preguntas técnicas; uno fraudulento las trata como deslealtad.</p><hr><h3>🕰️ La que no parece una estafa</h3><p>Y llegamos a la más peligrosa, que no se parece a ninguna de las anteriores.</p><p>No hay urgencia. No hay enlace sospechoso. Hay una <strong>relación que se construye durante semanas o meses</strong>: alguien que aparece en tu vida por otro motivo —una amistad, una conversación, un interés compartido— y que en algún momento, casi de pasada, menciona que le va bien con cierta inversión.</p><p>No insiste. No te pide nada. Espera a que preguntes tú, y eso lo cambia todo: cuando la idea parece tuya, las defensas no se activan.</p><p>Cuando por fin inviertes, todo funciona. Ves beneficios en una pantalla, puedes retirar cantidades pequeñas. El problema aparece al intentar sacar algo grande: impuestos inesperados, comisiones que hay que adelantar, una cuenta que se congela.</p><p>Funciona porque <strong>ataca la parte que ninguna herramienta protege</strong>: no tu cartera, sino tu juicio, y lo hace despacio.</p><p><strong>La única defensa que conozco:</strong> ninguna decisión sobre dinero debería tomarse dentro de la relación que la propone. Si la idea vino de alguien, que la evalúe alguien más.</p><hr><h3>🧪 Tres preguntas antes de actuar</h3><p>No hacen falta más reglas. Ante cualquier propuesta:</p><ol><li><p><strong>¿Hay prisa?</strong> Si la hay, y no la has puesto tú, es la señal más fiable de todas.</p></li><li><p><strong>¿Esto me lo puedo comprobar sin fiarme de quien me lo cuenta?</strong> Si la respuesta depende enteramente de su palabra, no es información.</p></li><li><p><strong>¿Qué pasa si espero una semana?</strong> Si la respuesta es «lo pierdes», ya tienes la respuesta.</p></li></ol><p>Esta lección cubre las estafas del ecosistema en general. Las que van específicamente contra una transacción —el portapapeles cambiado, las direcciones envenenadas, las aplicaciones falsas, los falsos recuperadores— se tratan en <em>Uso práctico de Bitcoin</em>, lección 1.3.</p><hr><h3>📌 En resumen</h3><ul><li><p>Casi todas siguen los mismos cuatro pasos: <strong>atención, confianza, prisa, acción irreversible</strong>. Reconocer la estructura vale más que memorizar el catálogo.</p></li><li><p><strong>Rentabilidad garantizada y cripto son incompatibles.</strong> Que paguen al principio es parte del método.</p></li><li><p>Nadie necesita acceso a tu cartera para <em>darte</em> algo. Firmar puede conceder un permiso, no cobrar un regalo.</p></li><li><p>La suplantación se detecta por el método —te escriben primero, te sacan del sitio oficial, meten prisa—, no por erratas.</p></li><li><p>En un proyecto fraudulento, <strong>preguntar cómo funciona algo molesta</strong>. En uno sólido, no.</p></li><li><p>La más peligrosa es lenta y sin urgencia: espera a que la idea parezca tuya. <strong>Ninguna decisión sobre dinero debería tomarse dentro de la relación que la propone.</strong></p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Las estafas son la mitad visible del problema. La otra mitad no tiene culpable: son los errores que comete gente que sabe perfectamente lo que hace. En la siguiente lección vemos <strong>cuáles cuestan dinero de verdad</strong> y por qué se cometen.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 1.3 errores-comunes-de-los-principiantes
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('232e0f52-ca6a-4308-9fdc-30c41c5abc69', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Errores comunes de los principiantes', 'errores-comunes-de-los-principiantes', 'Los errores que cuestan dinero no son de ignorancia. Por qué se cometen y cómo convertir lo que sabes en costumbre.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Entender los errores que de verdad cuestan dinero: no los que se cometen por ignorancia, sino los que comete gente que sabe lo que hace. Y por qué se cometen, que es lo que permite evitarlos.</p><hr><h3>🧠 El error no es no saber</h3><p>Conviene empezar por deshacer la explicación cómoda. Cuando alguien pierde fondos, la reacción habitual es pensar que no sabía lo suficiente. Casi nunca es eso.</p><p>La persona que envía a la dirección equivocada sabe que hay que comprobarla. La que guarda sus palabras en una foto sabe que no debería. La que deja su saldo en una plataforma durante meses sabe que sería mejor moverlo.</p><p><strong>El conocimiento estaba. Lo que faltó fue en el momento concreto.</strong></p><p>Eso cambia qué hacer al respecto: estudiar más no protege mucho. Lo que protege es convertir lo que ya sabes en algo que hagas sin decidirlo cada vez.</p><hr><h3>⏳ El error de «ya lo haré»</h3><p>Es el que más fondos se lleva y el único que no da ninguna señal mientras se comete.</p><p>La forma es siempre igual: configuras algo con prisa, te dices que lo dejarás bien más adelante, y ese «más adelante» no tiene fecha. La copia de seguridad que ibas a pasar a papel. La cantidad que ibas a mover de la plataforma. La recuperación que ibas a ensayar.</p><p>Lo que lo hace peligroso no es el descuido, sino que <strong>la ventana de arreglarlo se cierra sin avisar</strong>. Mientras nada falla, todo parece bien. El día que el dispositivo se rompe descubres que llevabas dos años sin copia, y ese día ya no es momento de hacerla.</p><p><strong>Lo que funciona:</strong> no dejar nada pendiente en la configuración inicial. Si no vas a hacer la copia ahora, no recibas fondos ahora. Es el único momento en que aplazar no cuesta nada.</p><hr><h3>🧺 Ponerlo todo en el mismo sitio</h3><p>Una sola cartera con todo. Una sola copia de seguridad. Una sola dirección de correo para todo. Una sola contraseña.</p><p>El problema no es que cada pieza sea débil: es que <strong>un solo fallo se lo lleva todo</strong>. Y como cada pieza por separado parece razonable, la concentración no se ve hasta que alguien la aprovecha.</p><p>El caso más frecuente es el correo. Es la llave de recuperación de casi todas tus cuentas, así que quien entra ahí puede restablecer contraseñas en cadena. Mucha gente protege su cartera con cuidado y deja el correo con una contraseña de hace diez años.</p><p>Cómo se reparte lo que guardas está en <em>Uso práctico de Bitcoin</em>; cómo se protege el correo y el resto de accesos, en el módulo siguiente de este curso.</p><hr><h3>📸 La copia cómoda</h3><p>Anotar las palabras de recuperación es incómodo, y todos los atajos que lo hacen cómodo tienen el mismo defecto: convierten un papel en un archivo.</p><p>Una foto acaba en la galería, y la galería se sincroniza. Un documento en la nube está donde estén las credenciales de esa nube. Un mensaje enviado a uno mismo vive en un servidor ajeno. Un gestor de contraseñas sincronizado concentra la llave de tu vida digital y la de tus fondos en el mismo sitio.</p><p>Ninguno requiere que alguien te ataque a ti. Basta con que ataquen al servicio.</p><p>Y hay una variante que casi nadie considera: <strong>anotarlas bien y no comprobar que la anotación funciona</strong>. Una palabra mal escrita o en el orden equivocado produce una copia que parece correcta durante años y falla el día que la necesitas. Cómo se comprueba está en <em>Cold Storage</em>.</p><hr><h3>🏃 La prisa ajena</h3><p>Ya apareció en la lección anterior como herramienta de quien estafa. Aquí interesa por otro motivo: <strong>también te la metes tú solo</strong>.</p><p>Hacer una operación mientras caminas. Firmar algo entre dos reuniones. Mover fondos porque el precio se mueve y sientes que hay que actuar ya.</p><p>Ninguna de esas situaciones implica mala fe de nadie, y todas reducen la atención justo cuando más hace falta. Las comprobaciones que vimos en <em>Uso práctico de Bitcoin</em> —dirección entera, unidad, red— no fallan porque se desconozcan: fallan porque se saltan cuando hay prisa.</p><p><strong>Lo que funciona:</strong> tener un sitio y un momento para estas cosas. Sentado, sin prisa, sin nadie esperando. Si no se dan las condiciones, no es el momento.</p><hr><h3>🤷 Confiar en que alguien está mirando</h3><p>Es el error más sutil y el que más crece con la costumbre.</p><p>Después de veinte operaciones que salieron bien, aparece la sensación de que el sistema te cubre: que si algo estuviera mal, saltaría un aviso. No hay tal aviso. La interfaz esconde complejidad, pero <strong>no asume responsabilidad</strong>, como ya vimos.</p><p>Lo llamativo es que este error empeora con la experiencia, no mejora. Quien lleva tres años operando sin incidentes baja la guardia más que quien empezó ayer, y suele manejar cantidades mayores.</p><p>Por eso las comprobaciones no son una fase de aprendizaje que se supera. Son permanentes, y la señal de que hacen falta es precisamente que lleves tiempo sin necesitarlas.</p><hr><h3>🔁 De conocimiento a costumbre</h3><p>Todo lo anterior apunta a la misma conclusión: lo que protege no es saber más, sino que lo que ya sabes ocurra solo.</p><p>Tres formas de conseguirlo, en orden de eficacia:</p><ul><li><p><strong>Reducir las decisiones.</strong> Si tienes una regla fija —siempre envío de prueba, siempre dirección entera— no hay nada que decidir en el momento, y por tanto nada que saltarse.</p></li><li><p><strong>Hacer difícil el atajo.</strong> Si lo que guardas no está en el teléfono, no puedes moverlo con prisa aunque quieras.</p></li><li><p><strong>Ensayar lo importante.</strong> Una recuperación probada es la diferencia entre creer que tienes una copia y tenerla.</p></li></ul><hr><h3>📌 En resumen</h3><ul><li><p>Los errores caros no son de ignorancia: <strong>el conocimiento estaba y faltó en el momento</strong>. Por eso protegen las costumbres, no estudiar más.</p></li><li><p><strong>«Ya lo haré»</strong> es el que más se lleva, y no da ninguna señal: la ventana de arreglarlo se cierra sin avisar. Si no vas a hacer la copia ahora, no recibas fondos ahora.</p></li><li><p>Concentrarlo todo hace que <strong>un solo fallo se lo lleve todo</strong>. El punto más descuidado suele ser el correo.</p></li><li><p>Los atajos cómodos para la copia convierten un papel en un archivo. Y una copia sin comprobar no es una copia.</p></li><li><p>La prisa también te la metes tú. Ten un sitio y un momento para estas cosas.</p></li><li><p>Confiar en que la interfaz te cubre <strong>empeora con la experiencia</strong>, no mejora.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya sabes qué falla. El siguiente módulo se ocupa de la parte que casi ningún curso de cripto trata y que sostiene todo lo demás: <strong>proteger los accesos</strong>. Contraseñas, segundo factor, dispositivos y las cuentas que son la llave de todo lo otro.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.1 claves-privadas-y-contrasenas
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('d8d05e6f-6659-46ea-b3dc-51f8c15998d8', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'Claves, contraseñas y segundo factor', 'claves-privadas-y-contrasenas', 'Tres cosas distintas con nombres parecidos, por qué el correo es la llave maestra y qué segundo factor elegir.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Distinguir tres cosas que se confunden constantemente —contraseña, clave privada y frase de recuperación—, y proteger bien la primera, que es la que casi nadie cuida y la que abre todas las demás puertas.</p><hr><h3>🧩 Tres cosas distintas con nombres parecidos</h3><p>Buena parte de los errores de esta lección vienen de mezclar conceptos que no tienen nada que ver.</p><ul><li><p><strong>Una contraseña</strong> la eliges tú y da acceso a un <em>servicio</em>: tu correo, una plataforma, el desbloqueo de una aplicación. Se puede cambiar, y si el servicio es serio, recuperar.</p></li><li><p><strong>Una clave privada</strong> no la elige nadie: es un número enorme generado al azar, y es lo que permite gastar unos fondos. No se cambia ni se recupera.</p></li><li><p><strong>La frase de recuperación</strong> son las palabras de las que salen todas tus claves privadas. Equivale a tenerlas todas a la vez.</p></li></ul><p>La consecuencia práctica: <strong>una contraseña protege un acceso; la frase ES el acceso</strong>. Por eso cambiar la contraseña de tu cartera no protege nada si alguien tiene tus palabras, y por eso ninguna contraseña que elijas puede compensar una frase mal guardada.</p><p>Lo que hace una contraseña sobre una cartera es impedir que quien coja tu teléfono opere con ella. Es útil y es otra cosa.</p><hr><h3>🔓 El correo es la llave maestra</h3><p>Aquí está el punto ciego más grande, y no tiene nada de cripto.</p><p>Tu dirección de correo es el mecanismo de recuperación de casi todas tus cuentas. Quien entra en ella puede pedir restablecer contraseñas en cadena: la plataforma donde operas, la copia en la nube, la tienda de aplicaciones desde la que instalas.</p><p>Es habitual ver a alguien proteger su cartera con mucho cuidado y tener el correo con una contraseña de hace años, reutilizada y sin segundo factor. <strong>El atacante no necesita romper lo fuerte si puede rodearlo.</strong></p><p>Si de esta lección solo te llevas una cosa, que sea esta: <strong>la cuenta de correo merece la protección más fuerte que tengas</strong>, por encima de cualquier otra.</p><hr><h3>🔑 Contraseñas: lo que importa de verdad</h3><p>Las reglas clásicas —mayúsculas, números, símbolos— importan menos de lo que se cree. Dos cosas importan mucho más:</p><p><strong>Que sean largas.</strong> La longitud gana a la complejidad. Una secuencia de cuatro o cinco palabras sin relación entre sí es más resistente que ocho caracteres con símbolos, y se recuerda mejor.</p><p><strong>Que no se repitan.</strong> Es lo más importante y lo que menos se cumple. Cuando un servicio cualquiera sufre una filtración —ocurre constantemente—, esa combinación de correo y contraseña se prueba automáticamente en todos los demás sitios. Una contraseña excelente reutilizada en diez sitios es tan débil como el peor de los diez.</p><p>Recordar contraseñas distintas para todo es imposible sin ayuda, y de ahí los gestores de contraseñas. Merecen un matiz: son una buena idea para tus cuentas, y hay que pensárselo dos veces antes de meter ahí la frase de recuperación, porque eso concentra en un solo sitio el acceso a tu vida digital y a tus fondos. Ya lo vimos en la lección anterior.</p><hr><h3>📲 El segundo factor, y cuál elegir</h3><p>El segundo factor añade algo que hay que tener, además de algo que hay que saber. Si alguien consigue tu contraseña, aún le falta.</p><p>No todos valen lo mismo, y la diferencia importa:</p><ul><li><p><strong>Por SMS.</strong> El más extendido y el más débil. Existe una técnica conocida por la que alguien consigue duplicar tu línea presentándose en una tienda con datos tuyos; a partir de ahí recibe tus códigos. Es mejor que nada, y es el que conviene evitar en las cuentas importantes.</p></li><li><p><strong>Con una aplicación de códigos.</strong> Genera un número que cambia cada pocos segundos, en tu dispositivo, sin depender de la línea telefónica. Es el equilibrio razonable para casi todo el mundo.</p></li><li><p><strong>Con una llave física.</strong> Un pequeño dispositivo que hay que tener delante. Es el más resistente, incluso frente a webs falsas, porque comprueba la dirección real del sitio antes de responder.</p></li></ul><p>Y un detalle que se pasa por alto siempre: al activar el segundo factor, casi todos los servicios te dan <strong>códigos de respaldo</strong>. Si pierdes el teléfono y no los tienes, te quedas fuera de tu propia cuenta. Guárdalos como guardarías algo importante, no en la misma aplicación que estás protegiendo.</p><hr><h3>🎣 Lo que el segundo factor no evita</h3><p>Conviene no darle más crédito del que tiene.</p><p>Si entras en una web falsa que imita a la real y escribes allí tu contraseña <em>y</em> tu código, quien está al otro lado puede usar ambos de inmediato en la web auténtica. El segundo factor no distingue si estás en el sitio correcto: solo comprueba que el código es válido.</p><p>Contra eso hay dos defensas, y ninguna es el segundo factor: <strong>llegar al sitio escribiendo tú la dirección</strong>, y usar una llave física, que sí verifica el dominio.</p><p>Dicho de otro modo: el segundo factor protege de que te roben la contraseña, no de que te convenzan de entregarla.</p><hr><h3>🚪 Revisar lo que ya has concedido</h3><p>Una costumbre que casi nadie tiene y que cuesta diez minutos al año.</p><p>Las cuentas acumulan accesos: sesiones abiertas en dispositivos que ya no usas, aplicaciones a las que diste permiso una vez, conexiones de terceros que olvidaste. Cada una es una puerta que sigue abierta.</p><p>Casi todos los servicios tienen una sección de seguridad donde se ven las sesiones activas y las aplicaciones autorizadas. Revisarla de vez en cuando y cerrar lo que no reconozcas es de las cosas más rentables que se pueden hacer en poco tiempo.</p><p>En el mundo cripto existe el equivalente: los permisos que concedes a aplicaciones para operar con tus fondos. Se revocan igual, y conviene hacerlo con lo que ya no uses.</p><hr><h3>📌 En resumen</h3><ul><li><p>Contraseña, clave privada y frase de recuperación son cosas distintas. <strong>Una contraseña protege un acceso; la frase ES el acceso.</strong></p></li><li><p><strong>El correo es la llave maestra</strong>: recupera todo lo demás. Merece tu protección más fuerte.</p></li><li><p>En contraseñas importa la <strong>longitud</strong> y sobre todo <strong>no repetirlas</strong>. Una excelente reutilizada es tan débil como el peor sitio donde la pusiste.</p></li><li><p>Segundo factor: el SMS es el más débil; una aplicación de códigos es el equilibrio razonable; una llave física, lo más resistente.</p></li><li><p>Guarda los <strong>códigos de respaldo</strong> del segundo factor, y no en la aplicación que protege.</p></li><li><p>El segundo factor <strong>no protege de una web falsa</strong> donde tú entregas ambos datos.</p></li><li><p>Revisa una vez al año las sesiones abiertas y los permisos concedidos.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Todo lo anterior se apoya en algo que damos por seguro sin pensarlo: <strong>el dispositivo desde el que lo haces</strong>. En la siguiente lección vemos por qué es parte del sistema de seguridad y qué lo convierte en el eslabón débil.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.2 dispositivos-y-seguridad
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('819b807b-0321-4e24-8987-dd14c51d3279', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'El dispositivo desde el que operas', 'dispositivos-y-seguridad', 'Por qué el dispositivo es parte de tu seguridad, las cuatro medidas que cubren casi todo y el riesgo de las extensiones.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Entender por qué el dispositivo desde el que operas forma parte de tu seguridad tanto como la cartera, y qué cuatro medidas concretas lo cubren casi todo sin convertirte en un experto en informática.</p><hr><h3>📱 El eslabón que no se mira</h3><p>Toda la protección que hemos visto —contraseñas largas, segundo factor, frases guardadas con cuidado— se apoya en un supuesto que nadie enuncia: <strong>que el dispositivo desde el que lo haces es de fiar</strong>.</p><p>Si no lo es, lo demás pierde gran parte de su valor. Un programa espía instalado en tu teléfono no necesita adivinar tu contraseña: la lee mientras la escribes. No necesita romper tu segundo factor: ve el código en la pantalla. No necesita descifrar nada: espera a que lo descifres tú.</p><p>Por eso el dispositivo no es «donde usas la seguridad». <strong>Es parte de la seguridad.</strong></p><hr><h3>🚪 Por dónde entra un problema</h3><p>No hay cien formas. En la práctica son cuatro, y tres de ellas requieren que tú hagas algo.</p><ul><li><p><strong>Instalar algo que no debías.</strong> Una aplicación fuera de las tiendas oficiales, un programa descargado de un enlace, una extensión del navegador que pedía permisos generosos. Es la vía más frecuente con diferencia.</p></li><li><p><strong>Abrir un archivo recibido.</strong> Un documento que alguien te envía, un instalador «actualizado», un archivo comprimido. Los documentos no son inofensivos por ser documentos.</p></li><li><p><strong>Software sin actualizar.</strong> Aquí no hace falta que hagas nada: basta con que no hagas. Las actualizaciones tapan agujeros que ya son públicos, y no instalarlas deja la puerta que todo el mundo sabe abierta.</p></li><li><p><strong>Acceso físico.</strong> Alguien que coge tu dispositivo desbloqueado. Menos común, y por eso mismo el más descuidado.</p></li></ul><hr><h3>🛡️ Las cuatro medidas que cubren casi todo</h3><p>Ordenadas por lo que aportan respecto a lo que cuestan.</p><p><strong>1. Actualizar, y que sea automático.</strong> Sistema operativo, navegador y aplicaciones. Es lo más eficaz y lo más aburrido. Si lo dejas en automático, deja de depender de tu memoria, que es exactamente el punto.</p><p><strong>2. Instalar solo desde el origen oficial.</strong> Las tiendas de aplicaciones del sistema y las webs oficiales de cada programa, llegando a ellas escribiendo tú la dirección. Ni enlaces de mensajes, ni resultados patrocinados de un buscador, ni repositorios alternativos.</p><p><strong>3. Bloqueo de pantalla y cifrado.</strong> Un código que no sea la fecha de tu cumpleaños, y el cifrado del disco activado. Los teléfonos modernos lo traen de serie; en ordenadores hay que comprobarlo. Convierte un robo en la pérdida de un aparato y no de todo lo que contiene.</p><p><strong>4. Menos cosas instaladas.</strong> Cada aplicación es superficie de ataque. Revisar lo que tienes y quitar lo que no usas reduce el problema sin esfuerzo continuo.</p><p>Con esas cuatro, un usuario normal está por encima de la media con bastante margen. Todo lo demás son matices.</p><hr><h3>🧩 Las extensiones del navegador</h3><p>Merecen un apartado propio porque son el punto ciego más grande en el mundo cripto.</p><p>Una extensión ve lo que ves y, según los permisos, puede modificar las páginas que visitas. Eso incluye cambiar una dirección mostrada en pantalla por otra, que es exactamente el ataque que más fondos se lleva.</p><p>Tres cosas que conviene saber:</p><ul><li><p><strong>Se actualizan solas.</strong> Una extensión honesta hoy puede cambiar de manos mañana, y la versión nueva llega sin que la apruebes. Ha ocurrido con extensiones populares compradas justamente para eso.</p></li><li><p><strong>Estar en la tienda oficial no garantiza nada.</strong> La revisión es superficial, y existen copias con nombres casi idénticos al original.</p></li><li><p><strong>El permiso que importa</strong> es el de leer y modificar datos en todos los sitios. Es enorme y se concede sin leerlo.</p></li></ul><p>La recomendación práctica es simple: tener pocas, revisarlas de vez en cuando, y quitar las que no uses. Si operas con cantidades que te importan, plantéate un navegador aparte, sin extensiones, solo para eso.</p><hr><h3>📶 Redes públicas: menos grave de lo que se cuenta</h3><p>Conviene desmontar un miedo desproporcionado, porque distrae de riesgos reales.</p><p>Hoy prácticamente todo el tráfico va cifrado de extremo a extremo entre tu dispositivo y el servidor. Quien esté escuchando en una red abierta no ve tus contraseñas ni el contenido de lo que haces.</p><p>Lo que sí puede hacer quien controla una red: <strong>redirigirte a una web falsa</strong> o mostrarte avisos pidiendo que instales algo. Fíjate en que ambos ataques vuelven a lo mismo de siempre —dónde llegas y qué instalas—, y no al hecho de que la red sea pública.</p><p>Lo razonable: en una red que no controlas, no instales nada y llega a los sitios importantes escribiendo tú la dirección. No hace falta más.</p><hr><h3>🔒 Separar por importancia</h3><p>La idea más útil de la lección, y no cuesta dinero.</p><p>No todo lo que haces tiene el mismo riesgo. Navegar, probar aplicaciones y abrir cosas que te mandan es actividad de alta exposición. Acceder a tus fondos, no.</p><p>Mezclar ambas en el mismo sitio significa que <strong>el riesgo de lo primero contamina lo segundo</strong>. Separarlas rompe esa conexión, y se puede hacer por grados:</p><ul><li><p><strong>Un navegador distinto</strong> para lo importante, sin extensiones. Coste: cero.</p></li><li><p><strong>Un perfil de usuario aparte</strong> en el mismo ordenador. Coste: unos minutos.</p></li><li><p><strong>Un dispositivo viejo reservado</strong> solo para esto, sin correo ni mensajería. Coste: un aparato que ya tienes.</p></li><li><p><strong>Un dispositivo dedicado</strong> que nunca se conecta a internet y guarda las claves. Es el salto grande, y es lo que se trata en <em>Cold Storage</em>.</p></li></ul><p>Cualquiera de los tres primeros mejora bastante la situación de partida. No hace falta empezar por el último.</p><hr><h3>📌 En resumen</h3><ul><li><p>El dispositivo no es donde usas la seguridad: <strong>es parte de la seguridad</strong>. Si está comprometido, no hace falta romper nada más.</p></li><li><p>Los problemas entran por cuatro sitios: lo que instalas, lo que abres, <strong>lo que no actualizas</strong> y quien coge el aparato desbloqueado.</p></li><li><p>Cuatro medidas cubren casi todo: actualizar en automático, instalar solo desde el origen oficial, bloqueo y cifrado, y tener menos cosas instaladas.</p></li><li><p>Las <strong>extensiones del navegador</strong> pueden modificar lo que ves —incluida una dirección— y se actualizan solas. Ten pocas y revísalas.</p></li><li><p>Las redes públicas preocupan más de lo que merecen: el riesgo real sigue siendo <strong>dónde llegas y qué instalas</strong>.</p></li><li><p><strong>Separar por importancia</strong> es la mejor relación entre lo que aporta y lo que cuesta. Empieza por un navegador aparte.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya tienes las piezas: accesos protegidos y un dispositivo de fiar. Falta convertirlas en algo que ocurra solo. La siguiente lección reúne <strong>el mínimo que debería cumplir cualquiera</strong>, ordenado y sin adornos.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.3 buenas-practicas-minimas-de-seguridad
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('7d0636ea-ba11-4f1f-bd3f-f48efebed28f', '920653af-6b9d-4e91-8c13-cfbf71d9a539', '9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'Buenas prácticas mínimas de seguridad', 'buenas-practicas-minimas-de-seguridad', 'El mínimo ordenado por lo que evita, cada cuánto se revisa y qué hacer si algo ya ha pasado.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Reunir en una sola lista el mínimo que debería cumplir cualquiera que tenga criptomonedas, ordenado por lo que evita y no por lo que suena bien. Y resolver la pregunta que nadie responde: cada cuánto hay que revisar esto.</p><hr><h3>🪜 Por qué hace falta un mínimo</h3><p>Los consejos de seguridad suelen llegar como una lista larga donde todo parece igual de urgente. El resultado previsible es que nadie hace nada, porque empezar cuesta demasiado.</p><p>Lo que sigue está ordenado. Las tres primeras medidas evitan la mayoría de las pérdidas reales; las siguientes añaden margen. <strong>Hacer las tres primeras vale mucho más que leerse las diez.</strong></p><hr><h3>🥇 Las tres que de verdad importan</h3><p><strong>1. Protege la cuenta de correo por encima de todo lo demás.</strong> Contraseña larga y única, segundo factor que no sea por SMS, y los códigos de respaldo guardados fuera del teléfono. Es la llave que recupera todas las demás cuentas, y es donde más gente está desprotegida.</p><p><strong>2. Ten una copia de la frase de recuperación, en papel, comprobada.</strong> Las tres partes cuentan. Que exista, que no sea un archivo, y que sepas que funciona porque lo has verificado. Una copia sin comprobar es una suposición.</p><p><strong>3. Comprueba antes de firmar.</strong> La dirección completa, la cantidad, la red. Es el único momento en que un error es irreversible, y dura diez segundos. El procedimiento detallado está en <em>Uso práctico de Bitcoin</em>.</p><p>Si solo vas a hacer tres cosas, que sean estas. Cubren el error humano, la pérdida de acceso y el robo por rodeo, que es de donde viene casi todo.</p><hr><h3>🥈 Las que añaden margen</h3><p><strong>4. Contraseñas distintas en todo.</strong> Con un gestor, porque de memoria es imposible. La frase de recuperación aparte, por lo que ya vimos.</p><p><strong>5. Actualizaciones automáticas activadas</strong> en sistema, navegador y aplicaciones.</p><p><strong>6. Instala solo desde el origen oficial</strong>, llegando tú a la dirección. Nunca desde un enlace que te llega.</p><p><strong>7. Reparte lo que guardas.</strong> Lo que usas a menudo por un lado, lo que no piensas tocar por otro. Que un fallo no se lleve el total.</p><p><strong>8. Separa el navegador</strong> con el que accedes a tus fondos del que usas para todo lo demás.</p><p><strong>9. No respondas a quien te escribe primero.</strong> Ni soporte, ni oportunidades, ni ayuda no pedida. En Nodo360 tampoco escribimos primero por privado.</p><p><strong>10. Revisa una vez al año</strong> las sesiones abiertas, los permisos concedidos y las aplicaciones que ya no usas.</p><hr><h3>🗓️ Cada cuánto se revisa esto</h3><p>La pregunta que falta en casi todas las listas. Sin una respuesta concreta, «revisar de vez en cuando» significa nunca.</p><ul><li><p><strong>Cada vez que operas:</strong> comprobar antes de firmar. No es una revisión, es parte de la operación.</p></li><li><p><strong>Una vez al año:</strong> sesiones abiertas, permisos concedidos, aplicaciones instaladas. Y comprobar que la copia de recuperación sigue donde crees y sigue siendo legible.</p></li><li><p><strong>Cuando algo cambia:</strong> te mudas, cambias de teléfono, cambias de correo, aumenta bastante lo que guardas. Cada uno de esos momentos invalida supuestos anteriores.</p></li></ul><p>El segundo es el que más se salta y el que más avisa a tiempo. Una copia en un sitio que ya no controlas o una tinta que se ha ido son fallos que se descubren tranquilamente en una revisión anual, o dramáticamente el día que hace falta.</p><hr><h3>🧯 Qué hacer si algo ya ha pasado</h3><p>Porque esta parte casi nunca se explica, y el orden importa.</p><p><strong>Si sospechas que alguien ha visto tu frase de recuperación:</strong> el orden es crear una cartera nueva, en un dispositivo de fiar, y mover los fondos allí. No sirve cambiar contraseñas: la frase no se cambia. Y hazlo ya, porque quien tiene la frase puede vaciar en cualquier momento.</p><p><strong>Si han entrado en tu correo:</strong> recupera el correo primero y solo después el resto. Al revés no funciona, porque con el correo pueden volver a entrar en todo lo que acabas de recuperar. Al recuperarlo, cierra todas las sesiones y revisa si hay reglas de reenvío creadas: es lo que más se pasa por alto.</p><p><strong>Si has firmado algo que no debías:</strong> revoca los permisos concedidos a esa aplicación y mueve lo que quede a una cartera nueva.</p><p><strong>Si has enviado a la dirección equivocada:</strong> aquí no hay procedimiento. No hay nadie a quien reclamar y quien te ofrezca recuperarlo está estafándote por segunda vez. Lo único que queda es que el error no se repita.</p><hr><h3>⚖️ Sobre el equilibrio</h3><p>Una advertencia para cerrar el módulo.</p><p>La seguridad que no puedes mantener no es seguridad. Un esquema tan complicado que te da pereza usarlo acaba abandonado a medias, y un sistema a medias suele ser peor que uno sencillo bien hecho.</p><p>La medida correcta no es la más estricta que existe: es <strong>la más estricta que vas a mantener durante años</strong>. Y esa depende de cuánto guardas, de cuánto operas y de cuánto tiempo estás dispuesto a dedicarle.</p><p>Por eso la lista de arriba está ordenada. Empieza por el principio, y sube cuando lo de abajo sea costumbre.</p><hr><h3>📌 En resumen</h3><ul><li><p>Las tres que importan: <strong>proteger el correo</strong>, <strong>una copia en papel comprobada</strong> y <strong>comprobar antes de firmar</strong>. Cubren casi todas las pérdidas reales.</p></li><li><p>Las siete siguientes añaden margen, no sustituyen a las tres primeras.</p></li><li><p>Revisión: en cada operación, una vez al año, y cada vez que algo cambia en tu vida.</p></li><li><p>Si ha pasado algo, <strong>el orden importa</strong>: el correo se recupera antes que lo demás; ante una frase expuesta, cartera nueva y mover ya.</p></li><li><p>Quien te ofrece recuperar fondos enviados por error está estafándote.</p></li><li><p>La medida correcta es <strong>la más estricta que vas a mantener durante años</strong>, no la más estricta que existe.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Sabes protegerte y sabes qué hábitos sostener. Queda la decisión de fondo, la que ordena todo lo demás: <strong>quién guarda lo que tienes</strong>. El último módulo trata la custodia —qué significa exactamente, qué opciones hay y cómo elegir con criterio en vez de por consigna.</p>')
