  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- ============================================================================
-- 4. Quiz: 27 preguntas, 9 por modulo
-- ============================================================================
-- Las 5 anteriores se sustituyen. Los 3 intentos ya registrados no se pierden:
-- quiz_attempts no tiene clave ajena contra quiz_questions.

DELETE FROM public.quiz_questions WHERE module_id IN ('7b2773a3-5633-4242-a099-d3a2c2622ca2', '9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'ccc49b50-8138-45fd-afbe-9ed50b2e6b5b');

-- M1 Los riesgos reales
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', '¿Cuál de estos trabajos hace un banco por ti y deja de hacerlo nadie cuando custodias tú?', 'Un banco no solo guarda dinero: vigila el fraude, deshace errores, te devuelve el acceso, guarda copias y responde con un fondo de garantía. De todos ellos, devolverte el acceso es el que desaparece por completo: nadie puede restablecer una clave privada.', '["Confirmar que la red ha recibido tu transacción","Devolverte el acceso si pierdes tus credenciales","Mostrarte el saldo actualizado","Cobrarte comisiones por operar"]'::jsonb, 1, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Al asumir la custodia, ¿qué cuatro trabajos pasan a ser tuyos?', 'No es una idea abstracta de libertad: es un traspaso de tareas concretas. Verlas enumeradas es lo que permite repartirlas entre los módulos de este curso y saber cuál te falta.', '["Minar, validar, firmar y difundir","Comprar, vender, declarar y custodiar","Custodia, recuperación, verificación y detección de engaños","Cifrado, respaldo, auditoría y seguros"]'::jsonb, 2, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Se dice que lo que ganas con la autocustodia es permanente y pasivo, y lo que pagas es puntual y activo. ¿Qué consecuencia práctica tiene eso?', 'El riesgo no se reparte de forma uniforme en el tiempo: se concentra en unos pocos instantes —cuando configuras, cuando firmas, cuando alguien te escribe— y es despreciable el resto. Por eso no hace falta vivir en tensión, sino reconocer esos momentos.', '["Que conviene mantener desconfianza constante mientras tengas fondos","Que el riesgo se concentra en pocos momentos concretos y basta con bajar el ritmo en ellos","Que la autocustodia solo compensa a partir de cierta cantidad","Que el riesgo crece de forma proporcional al tiempo que pasa"]'::jsonb, 1, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Te llega una propuesta de inversión que garantiza un 8 % mensual y muestra pagos reales a otros participantes. ¿Qué te dice eso?', 'En cripto nadie puede garantizar un rendimiento, porque el valor de lo que hay debajo no lo controla nadie. Que paguen al principio no desmiente la estafa: es parte del método, porque convierte a los primeros en recomendadores convencidos.', '["Que el proyecto es sólido, porque los pagos se pueden comprobar","Que conviene entrar con poco para probar","Que la rentabilidad garantizada es incompatible con cripto, y los pagos iniciales forman parte del método","Que hay que comprobar si está registrado antes de decidir"]'::jsonb, 2, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', '¿Qué cuatro pasos comparten casi todas las estafas del ecosistema?', 'La apariencia cambia cada temporada; la estructura no. Reconocer estos cuatro pasos sirve incluso con estafas que todavía no existen, y por eso vale más que memorizar el catálogo de las actuales.', '["Publicidad, registro, depósito y bloqueo","Atención, confianza, prisa y acción irreversible","Contacto, contrato, comisión y desaparición","Promesa, prueba, testimonio y garantía"]'::jsonb, 1, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'De todas las estafas vistas, ¿cuál es la más peligrosa y por qué?', 'No tiene urgencia ni enlaces sospechosos: construye una relación durante semanas y espera a que preguntes tú. Cuando la idea parece tuya, las defensas no se activan. Ataca el juicio, que es lo que ninguna herramienta protege.', '["La suplantación del soporte técnico, porque imita bien a la empresa","El falso airdrop, porque te hace firmar sin entender","La relación construida lentamente, porque espera a que la idea parezca tuya","La web falsa, porque captura la contraseña y el código a la vez"]'::jsonb, 2, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'En el mundo cripto, ¿cuál es la causa real de la mayoría de los errores que cuestan dinero?', 'La persona que envía a la dirección equivocada sabe que hay que comprobarla. El conocimiento estaba; lo que faltó fue en el momento concreto. Por eso estudiar más no protege mucho y convertir lo que ya sabes en costumbre sí.', '["Fallos técnicos de las aplicaciones de cartera","Desconocimiento: falta formación previa","Que el conocimiento estaba pero no se aplicó en el momento","Ataques sofisticados difíciles de detectar"]'::jsonb, 2, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', '¿Por qué es especialmente peligroso el error de «ya lo haré más adelante»?', 'Mientras nada falla, todo parece bien. El día que el dispositivo se rompe descubres que llevabas dos años sin copia, y ese día ya no es momento de hacerla. Por eso conviene no dejar nada pendiente en la configuración inicial.', '["Porque las aplicaciones cambian y la configuración deja de servir","Porque no da ninguna señal mientras se comete y la ventana de arreglarlo se cierra sin avisar","Porque las comisiones suben con el tiempo","Porque la red deja de aceptar carteras antiguas"]'::jsonb, 1, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('7b2773a3-5633-4242-a099-d3a2c2622ca2', 'Llevas tres años operando sin ningún incidente. ¿Qué efecto tiene eso sobre tu seguridad?', 'Confiar en que el sistema te cubre empeora con la experiencia, no mejora: quien lleva tiempo sin incidentes baja la guardia más que quien empezó ayer, y suele manejar cantidades mayores. Las comprobaciones no son una fase que se supera.', '["Ninguno: la seguridad depende solo de las herramientas","Mejora, porque ya reconoces los riesgos por costumbre","Empeora, porque la costumbre baja la guardia justo cuando las cantidades son mayores","Mejora, porque los ataques se concentran en principiantes"]'::jsonb, 2, 9, 'medium', 1);


-- M2 Proteger tus accesos
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', '¿Qué diferencia esencial hay entre una contraseña y una frase de recuperación?', 'Una contraseña protege un acceso y se puede cambiar; la frase ES el acceso y no se cambia ni se recupera. Por eso cambiar la contraseña de tu cartera no protege nada si alguien tiene tus palabras.', '["La frase es más larga, pero ambas se pueden restablecer","Una contraseña protege un acceso; la frase es el acceso en sí","La contraseña la genera el sistema y la frase la eliges tú","Ninguna: son dos nombres para lo mismo"]'::jsonb, 1, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'Proteges tu cartera con mucho cuidado, pero tu correo tiene una contraseña de hace años sin segundo factor. ¿Qué problema hay?', 'El correo es el mecanismo de recuperación de casi todas tus cuentas: quien entra ahí puede restablecer contraseñas en cadena. El atacante no necesita romper lo fuerte si puede rodearlo.', '["Ninguno, mientras la cartera esté bien protegida","Que el correo es la llave que recupera todo lo demás, así que rodea la protección de la cartera","Que el proveedor de correo podría leer tus claves","Que conviene cambiar de proveedor de correo cada año"]'::jsonb, 1, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'De estas dos contraseñas, ¿cuál protege mejor y por qué?', 'La longitud gana a la complejidad, y no repetirla es aún más importante: cuando un servicio cualquiera sufre una filtración, esa combinación se prueba automáticamente en los demás sitios. Una contraseña excelente reutilizada es tan débil como el peor sitio donde la pusiste.', '["Ocho caracteres con símbolos, usada solo ahí","Cinco palabras sin relación entre sí, usada solo ahí","Ocho caracteres con símbolos, usada en varios sitios","Da igual: lo único que importa son los símbolos"]'::jsonb, 1, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', '¿Cuál de estos segundos factores conviene evitar en las cuentas importantes?', 'Existe una técnica conocida por la que alguien duplica tu línea telefónica presentándose con datos tuyos, y a partir de ahí recibe tus códigos. Es mejor que nada, pero es el más débil de los tres.', '["Una aplicación de códigos que cambian cada pocos segundos","Una llave física que hay que tener delante","Los códigos recibidos por SMS","Los tres son equivalentes en seguridad"]'::jsonb, 2, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'Entras en una web que imita a la real y escribes tu contraseña y tu código del segundo factor. ¿Te protege el segundo factor?', 'El segundo factor no distingue si estás en el sitio correcto: solo comprueba que el código es válido, y quien está al otro lado puede usar ambos de inmediato en la web auténtica. Protege de que te roben la contraseña, no de que te convenzan de entregarla.', '["Sí, porque el código caduca en segundos","Sí, siempre que sea una aplicación y no un SMS","No: quien recibe ambos datos puede usarlos al instante en la web auténtica","No, pero solo si la web tiene un certificado inválido"]'::jsonb, 2, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', '¿Por qué el dispositivo desde el que operas forma parte de tu seguridad y no es solo el sitio donde la usas?', 'Un programa espía no necesita adivinar tu contraseña: la lee mientras la escribes; no necesita romper el segundo factor: ve el código en pantalla. Si el dispositivo no es de fiar, lo demás pierde gran parte de su valor.', '["Porque los dispositivos almacenan las monedas","Porque si está comprometido no hace falta romper ninguna de las otras protecciones","Porque el sistema operativo firma las transacciones por ti","Porque determina las comisiones que pagas"]'::jsonb, 1, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'De estas cuatro medidas sobre el dispositivo, ¿cuál es la más eficaz respecto a lo que cuesta?', 'Las actualizaciones tapan agujeros que ya son públicos, y dejarlas en automático hace que deje de depender de tu memoria, que es exactamente el punto. Es lo más eficaz y lo más aburrido.', '["Instalar un antivirus de pago","Tener las actualizaciones automáticas activadas","Usar una red privada virtual siempre","Cambiar de dispositivo cada dos años"]'::jsonb, 1, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', '¿Qué riesgo concreto tienen las extensiones del navegador en el mundo cripto?', 'Una extensión ve lo que ves y, según los permisos, puede modificar las páginas que visitas: eso incluye cambiar una dirección mostrada en pantalla. Además se actualizan solas, así que una extensión honesta hoy puede cambiar de manos mañana.', '["Consumen memoria y ralentizan las operaciones","Pueden modificar lo que ves, incluida una dirección, y se actualizan sin que lo apruebes","Impiden que el segundo factor funcione","Revelan tu dirección IP a la red"]'::jsonb, 1, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9e53d5c2-accd-4b4f-a7a9-e18af4ae6e4b', 'Si solo vas a aplicar tres medidas de seguridad, ¿cuáles son?', 'Cubren el error humano, la pérdida de acceso y el robo por rodeo, que es de donde viene casi todo. Las demás medidas añaden margen, pero no sustituyen a estas tres.', '["Antivirus, red privada virtual y contraseñas con símbolos","Proteger el correo, tener una copia en papel comprobada y comprobar antes de firmar","Cambiar contraseñas cada mes, cifrar el disco y usar dos navegadores","Dispositivo dedicado, custodia repartida y revisión mensual"]'::jsonb, 1, 9, 'medium', 1);


-- M3 La custodia, decidida con criterio
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '¿Qué guarda exactamente una cartera de criptomonedas?', 'Las unidades están anotadas en el registro compartido que mantienen miles de ordenadores. Lo que guarda una cartera es la clave que permite ordenar movimientos desde una dirección, y nada más. Por eso romper el dispositivo no destruye los fondos.', '["Las monedas, en un archivo cifrado","La clave que permite firmar movimientos desde una dirección","Una copia del registro completo de la red","Un certificado de propiedad emitido por la red"]'::jsonb, 1, 1, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', 'Se dice que custodiar bien no es maximizar una defensa sino encontrar un punto. ¿Por qué?', 'Protegerte del robo empuja a tener menos copias y más escondidas; protegerte de la pérdida empuja a tener más y más accesibles. Llevar cualquiera de las dos al extremo produce el otro fallo, y ambos son igual de definitivos.', '["Porque el coste de las medidas crece con la cantidad custodiada","Porque las defensas contra el robo y contra la pérdida de acceso tiran en direcciones contrarias","Porque la red penaliza las carteras con demasiadas copias","Porque la ley limita el número de respaldos permitidos"]'::jsonb, 1, 2, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '¿Qué prueba sencilla revela si hay un custodio de por medio, lo diga la aplicación o no?', 'Si no puedes enviar fondos a una dirección cualquiera ahora mismo, sin permiso de nadie y sin que nadie pueda impedirlo, lo que tienes es un derecho frente a una empresa, no la clave. Es la diferencia entre las dos formas de «tener».', '["Si la aplicación muestra el saldo en euros","Si puedes enviar a cualquier dirección ahora mismo sin que nadie pueda impedirlo","Si la aplicación te pide verificar tu identidad","Si cobra comisiones por retirar"]'::jsonb, 1, 3, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '¿Cuál de estas formas de perder fondos con un custodio es la más frecuente y la menos prevista?', 'El bloqueo de cuenta no requiere mala fe ni catástrofe: puede venir de una revisión, una orden judicial o un error. Es la forma más habitual de quedarse sin acceso temporalmente, y llega sin aviso.', '["Que la empresa quiebre","Que la ataquen y el robo supere lo que puede absorber","Que bloquee tu cuenta por una revisión, una orden o un error","Que desaparezca llevándose lo depositado"]'::jsonb, 2, 4, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', 'Puesto en una frase, ¿qué protege cada opción de custodia?', 'Con un custodio, olvidar la contraseña tiene solución y alguien vigila accesos raros; a cambio dependes de que siga existiendo y dejándote operar. Custodiando tú, nadie puede congelar ni quebrar, pero un error tuyo no tiene marcha atrás.', '["El custodio protege de los errores de otros; la custodia propia, de los tuyos","El custodio protege de tus errores; la custodia propia, de los errores de otros","Ambas protegen de lo mismo, con distinto coste","El custodio protege del robo; la custodia propia, de la inflación"]'::jsonb, 1, 5, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '¿Cuál de estos riesgos de la custodia propia es el que menos se prevé, por incómodo?', 'Una custodia perfecta que nadie más puede abrir es una pérdida garantizada para quien venga después. Es un problema resoluble, pero hay que resolverlo a propósito, porque no se resuelve solo.', '["Perder la frase de recuperación","Que alguien consiga la frase mediante un engaño","Enviar a una dirección equivocada","Que te pase algo y nadie más pueda acceder"]'::jsonb, 3, 6, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', 'Sabes que no vas a revisar nada durante los próximos cinco años. ¿Qué opción de custodia tiene más sentido?', 'La custodia propia exige trabajo que no termina: comprobar la copia, mantenerla legible, verificar cada operación, revisar de vez en cuando. Mal mantenida es peor que un custodio decente, porque suma los riesgos sin las ventajas.', '["Custodia propia con dispositivo dedicado, por ser la más segura sobre el papel","Un custodio decente, porque una autocustodia abandonada suma riesgos sin las ventajas","Custodia repartida entre varias firmas","Da igual: el mantenimiento no afecta al resultado"]'::jsonb, 1, 7, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', 'Según el curso, ¿qué señal permite detectar un problema sin entender nada del asunto concreto?', 'Las estafas introducen urgencia como paso obligatorio, los errores caros se cometen con prisa y las comprobaciones se saltan cuando hay que ir rápido. La prisa que no has puesto tú es motivo suficiente para parar; casi nada legítimo se estropea por esperar un día.', '["Las faltas de ortografía en el mensaje","Un logotipo mal reproducido","La prisa que no has puesto tú","Que el remitente sea desconocido"]'::jsonb, 2, 8, 'medium', 1);

INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ccc49b50-8138-45fd-afbe-9ed50b2e6b5b', '¿Por qué un sistema de seguridad sencillo puede proteger más que uno complejo?', 'Un esquema complejo suele terminar a medias, sin ensayar y con piezas que nadie recuerda dónde están. Y la complejidad no solo añade trabajo: añade formas nuevas de fallar. La medida correcta es la más estricta que vas a mantener durante años.', '["Porque las herramientas sencillas están mejor auditadas","Porque se mantiene durante años y la complejidad añade formas nuevas de fallar","Porque cuesta menos dinero","Porque los atacantes se centran en los sistemas complejos"]'::jsonb, 1, 9, 'medium', 1);

-- ============================================================================
-- 5. Ficha del curso
-- ============================================================================

UPDATE public.courses SET
  description = 'Reconoce las estafas, protege tus accesos y decide con criterio quién custodia lo que tienes.',
  long_description = 'Usar Bitcoin y criptomonedas implica asumir trabajos que en el sistema financiero hace otro por ti sin que te enteres: vigilar el fraude, deshacer errores y devolverte el acceso cuando lo pierdes.

Este curso recorre esos trabajos en tres partes. Los riesgos reales del ecosistema, con las estafas y los errores que de verdad cuestan dinero. La protección de los accesos: contraseñas, segundo factor, dispositivos y las cuentas que son la llave de todas las demás. Y la custodia, con los criterios para decidir qué parte guardas tú y qué parte delegas.

No parte de que la autocustodia sea mejor. Enseña a hacerla bien si decides hacerla, y a reconocer cuándo no estás preparado para una cantidad determinada.',
  total_modules = 3,
  total_lessons = 9
 WHERE id = '920653af-6b9d-4e91-8c13-cfbf71d9a539';

-- ============================================================================
-- 6. Rutas: Cold Storage cambia de ruta y "Seguridad Avanzada" desaparece
-- ============================================================================

UPDATE public.learning_path_courses SET learning_path_id = '594ec9e8-a7e8-41f9-9ece-e4ef286946d1', position = 1
 WHERE id = 'af1b51c9-11b5-4385-a5d4-d5d0839424bf';  -- cold-storage-protege-tus-bitcoin

DELETE FROM public.learning_paths WHERE id = 'f48e5141-5633-40c2-9e21-608e377230fc';  -- seguridad-avanzada

-- Los dos cursos de custodia se archivan. Sus filas de learning_path_courses
-- se conservan: RLS deja de servir el curso a un usuario normal, el embed
-- devuelve NULL y la ruta no los muestra (igual que el curso monetario).
UPDATE public.courses SET status = 'archived' WHERE id = '87ef901f-7382-4ada-bb48-ea0f89b726f6';  -- custodia-y-proteccion-de-tus-fondos
UPDATE public.courses SET status = 'archived' WHERE id = '05706395-44ac-4a61-a493-55478cb3639b';  -- custodia-y-proteccion-practica-de-criptomonedas

-- ============================================================================
-- 7. Devolver el curso a 'published'
-- ============================================================================
-- Necesario solo si el disparador de la 030 llego a actuar (ver la cabecera).
-- Con SET LOCAL app.skip_republish_check no hace falta, pero es inofensivo:
-- filtra por el estado actual para no revivir un curso mandado a revision a
-- proposito, y al cambiar solo status el disparador sale por su primera
-- condicion.

UPDATE public.courses SET status = 'published', updated_at = now()
 WHERE id = '920653af-6b9d-4e91-8c13-cfbf71d9a539' AND status = 'pending_review';

-- ============================================================================
-- 8. Porcentajes de progreso
-- ============================================================================
-- El curso pasa de 6 a 9 lecciones: quien lo tenia al 100% con las 6 hechas
-- pasa a 67%. completed_at no se toca ni al aplicar ni al revertir, y el
-- disparador de certificados es AFTER UPDATE OF completed_at, asi que tocar
-- solo el porcentaje no emite nada.
UPDATE public.course_enrollments SET progress_percentage = 67
 WHERE id = '210bd3a8-47b2-4958-9bd0-ac2588940717';  -- 34c7dd0a, completed_at intacto
UPDATE public.course_enrollments SET progress_percentage = 67
 WHERE id = '66703818-f03e-4278-bb46-5704b27829e6';  -- ab354bca, completed_at intacto

COMMIT;

